"""Frozen English data-production tasks; independent reference never receives proposal."""
import json
COMMON='''Use only the supplied judgment. No external searches, other conversations, old answers or prior model reviews. This is judgment-reasoning reconstruction, not prediction. Preserve court level, stage, attributed statements, objects, dates, alternatives and important contrary material. A party claim is usable to establish that a claim was made, not automatically to establish the underlying occurrence. A legal rule or facts in a cited precedent cannot establish target-case events. Do not use the final disposition as a circular premise proving itself. Unproved does not mean false. Source addresses are not legal approval. Work in English. Return one complete JSON object; do not require follow-up. All outputs are unverified model proposals/references, not human gold. Exact quotes may be separate excerpts, never invent continuous text. Do not rewrite the supplied source.'''
CONTRACT={
 'facts':[{'id':'F1','text':'Witness Ada asserted Monday access to Lot A.','statement_status':'TESTIMONY','speaker':'Ada','court_level':'trial','stage':'testimony','bindings':{'speaker':'Ada','property':'Lot A'},'time_scope':'Monday','refs':['DEMO:L1'],'quote':'Ada testified that she entered Lot A on Monday.'}],
 'rules':[{'id':'R1','version':1,'description':'Fictional teaching rule: a recorded testimony establishes only the attributed assertion.','source_refs':['DEMO:L2'],'source_quote':'A testimony record supports the attribution of the assertion, not automatic proof of entry.','jurisdiction':'fictional','stage':'attribution','operator':'ALL','conclusion':'The access assertion is recorded.','premises':[{'id':'R1.P1','text':'Ada testified to entry on Lot A on Monday.','family':'STATEMENT_STATUS','allowed_statuses':['TESTIMONY'],'variables':{'speaker':'witness','property':'land'},'expected':'TRUE'}],'exceptions':[],'limits':['This does not decide whether entry occurred.']}],
 'uses':[{'id':'U1','request_id':'Q1','rule_premise':'R1.P1','evidence_ids':['F1'],'bindings':{'witness':'Ada','land':'Lot A'},'relevance':'RELATED','use_judgment':'USABLE','premise_state':'TRUE','basis':'The record explicitly attributes this statement to the witness; occurrence remains unverified.','opposition':[],'gaps':[]}],
 'targets':[{'id':'Q1','rule_ids':['R1'],'limited_conclusion':'The testimony assertion is recorded; actual entry remains undecided.'}],
 'relations':[],'coverage_limits':['Synthetic illustration only; DEMO IDs are not target sources.']}
LABELCONTRACT={'use_reviews':[{'use_id':'U1','label':'USABLE','refs':['DEMO:L1'],'quote':'Ada testified that she entered Lot A on Monday.','basis':'The proposed use is attribution only.','major_opposition':[],'gap':None}], 'coverage_limits':[]}
REFERENCECONTRACT={'targets':[{'id':'Q1','necessary_premises':[{'text':'Ada made an access assertion.','status':'TESTIMONY','bindings':{'speaker':'Ada','property':'Lot A'},'refs':['DEMO:L1'],'quote':'Ada testified that she entered Lot A on Monday.'}],'rules':[{'text':'Fictional attribution rule only.','refs':['DEMO:L2'],'quote':'A testimony record supports the attribution of the assertion, not automatic proof of entry.','scope':'Attribution only'}],'major_opposition':[],'gaps':['Actual entry is not proved by attribution alone.'],'limited_conclusion':'The assertion is recorded; its truth remains unverified.'}], 'coverage_limits':[]}

def task(kind,case,proposal=None):
 prefix=COMMON+'\nCASE ID: '+case['case_id']+'\nQUESTIONS:\n'+json.dumps(case['targets'],ensure_ascii=False)+'\n'
 if kind=='proposal':
  direction='''Generate raw fact and candidate-use proposals. Translate only rules actually expressed/adopted in this judgment, preserving reported precedent status and open legal evaluation (OPEN_TEXT). Each rule premise needs a full proposition, stable local ID, permitted statement statuses, object variables, and expected polarity. ALL/ANY and exceptions must have explicit source support; otherwise OPEN_TEXT. Keep each evidence record once, then distinct evidence-to-premise uses. An evidence bundle may fill a compound premise only when its full coverage is justified. Use judgments USABLE/UNUSABLE/UNRESOLVED concern the specified use; premise_state TRUE/FALSE/UNKNOWN/CONFLICTED is a separate whole-premise proposal. SUPPORT alone never suffices. Include realistic alternatives already in the source, not artificial negative permutations. Preserve incompatible uses if they are meaningful candidate interpretations and explain why. Unknown bindings remain null, not wildcard. Aim for a manageable 10–25 material uses if warranted, not a quota. Do not force every fact to every premise. One actual arrangement can have conflicting accounts without becoming two events. Legal concepts/families organize premises, not individual identity. The example is fully synthetic, not a rule for this case. Write only task-relevant structures; do not turn every paragraph into a fact.\nEXAMPLE OUTPUT (fictional teaching sources):\n'''+json.dumps(CONTRACT)
 elif kind=='reference':
  if proposal is not None:raise ValueError('REFERENCE_MUST_BE_PROPOSAL_BLIND')
  direction='Independently read the source for both fixed questions. Record necessary premises, their statement status, bindings, adopted rules/scope, major contrary arguments and genuine gaps. No proposal or candidate IDs are supplied. Cover decisive source content even when not favorable to the final disposition. Use this complete synthetic shape, filling both Q1 and Q2: '+json.dumps(REFERENCECONTRACT)
 elif kind=='review':
  if proposal is None:raise ValueError('FROZEN_PROPOSAL_REQUIRED')
  direction='Review each frozen proposed use against the complete source. Do not edit the proposal. Label USABLE only for its precise premise, status, object, time and inferential scope. Label UNUSABLE only for an explicit source-grounded incompatibility; UNRESOLVED for real unresolved interpretation or insufficiency; UNLABELED if unreviewed. Do not treat missing review as negative. Distinguish relevant evidence from sufficient proof. Preserve contradictory source evidence. No independent reference answer is supplied. Exact source quote and address plus brief reason are required for each reviewed use. Synthetic output shape: '+json.dumps(LABELCONTRACT)+'\nFROZEN RAW PROPOSAL:\n'+json.dumps(proposal,ensure_ascii=False)
 else:raise ValueError(kind)
 body='\n\n'.join('['+s['id']+']\n'+s['text'] for s in case['segments'])
 return prefix+direction+'\n\nCOMPLETE ALLOWED JUDGMENT RENDERING (frontmatter, headnotes, party submissions and final reasoning must retain their own status):\n'+body+'\nEND OF PROVIDED SOURCE. Return the complete English JSON once.'
